/**
 * The predicate-range anchor replaces {@code FILTER(?o = c)} by a term-identity JOIN with VALUES, so when it falls back
 * to enumerating a finite stored domain it must select every stored term that SPARQL value-equals the constant, not
 * only the term that {@code equals} it. Where strict and extended comparison modes disagree it must refuse.
 */
class PackedFiniteAnchorValueEqualityTest {

	private static final IRI D = iri("d");
	private static final IRI U = iri("u");

	/** {@code :d} holds two xsd:date terms (finite, no canonical-date proof). */
	private static final PackedPredicateRangeProvider FINITE_DATE_PROVIDER = finiteProvider(D, CoreDatatype.XSD.DATE,
			"2020-01-01", "2021-06-30");

	/** {@code :u} holds two xsd:duration terms; {@code P12M} value-equals {@code P1Y} only in extended mode. */
	private static final PackedPredicateRangeProvider FINITE_DURATION_PROVIDER = finiteProvider(U,
			CoreDatatype.XSD.DURATION, "P12M", "P2Y");

	private static PackedPredicateRangeProvider finiteProvider(IRI predicate, CoreDatatype.XSD datatype,
			String... lexicals) {
		return new PackedPredicateRangeProvider() {
			@Override
			public boolean describeObjectRange(IRI candidate, PackedPredicateRange output) {
				if (!predicate.equals(candidate)) {
					return false;
				}
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_LITERAL);
				output.setLanguageBits(PackedPredicateRange.LANGUAGE_WITHOUT);
				output.addDatatype(datatype);
				output.setFinite(true);
				for (String lexical : lexicals) {
					output.addFiniteValue(VF.createLiteral(lexical, datatype));
				}
				return true;
			}

			@Override
			public long predicateRangeVersion() {
				return 21L;
			}
		};
	}

	private static final Set<Value> VALUE_EQUAL_TO_ONE = Set.of(VF.createLiteral("1", CoreDatatype.XSD.INTEGER),
			VF.createLiteral("01", CoreDatatype.XSD.INTEGER), VF.createLiteral("1.0", CoreDatatype.XSD.DECIMAL));

	// ------------------------------------------------------------------ reviewer's shapes

	@Test
	void finiteFallbackAnchorKeepsEveryValueEqualStoredTerm() {
		TupleExpr selected = assertPackedPlanPreservesResults(nonCanonicalNumericData(),
				"SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1) }", SUBJECT_LOOKUP_COSTS, NON_CANONICAL_NUMERIC_PROVIDER,
				List.of("s=urn:t:s1", "s=urn:t:s2", "s=urn:t:s3"));
		assertEquals(List.of(VALUE_EQUAL_TO_ONE), finiteDomains(selected, "o"),
				"the anchor must enumerate 1, 01 and 1.0 (all value-equal to 1): " + selected);
	}

	@Test
	void finiteFallbackAnchorForDecimalConstantKeepsEveryValueEqualStoredTerm() {
		TupleExpr selected = assertPackedPlanPreservesResults(nonCanonicalNumericData(),
				"SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1.0) }", SUBJECT_LOOKUP_COSTS, NON_CANONICAL_NUMERIC_PROVIDER,
				List.of("s=urn:t:s1", "s=urn:t:s2", "s=urn:t:s3"));
		assertEquals(List.of(VALUE_EQUAL_TO_ONE), finiteDomains(selected, "o"), String.valueOf(selected));
	}

	@Test
	void anchorInsideJoinKeepsValueEqualTermsForTheSibling() {
		assertPackedPlanPreservesResults(nonCanonicalNumericData(),
				"SELECT ?s ?t WHERE { ?s :v ?o FILTER(?o = 1) ?t :w ?o }", SUBJECT_LOOKUP_COSTS,
				NON_CANONICAL_NUMERIC_PROVIDER, List.of("s=urn:t:s3|t=urn:t:t1"));
	}

	@Test
	void anchorInsideNestedGroupKeepsValueEqualTermsForTheSibling() {
		assertPackedPlanPreservesResults(nonCanonicalNumericData(),
				"SELECT ?s ?t WHERE { { ?s :v ?o FILTER(?o = 1) } ?t :w ?o }", SUBJECT_LOOKUP_COSTS,
				NON_CANONICAL_NUMERIC_PROVIDER, List.of("s=urn:t:s3|t=urn:t:t1"));
	}

	@Test
	void anchorKeepsValueEqualTermsForSiblingDatatypeFilter() {
		assertPackedPlanPreservesResults(nonCanonicalNumericData(),
				"SELECT ?s WHERE { ?s :v ?o FILTER(?o = 1) FILTER(datatype(?o) = xsd:decimal) }",
				SUBJECT_LOOKUP_COSTS, NON_CANONICAL_NUMERIC_PROVIDER, List.of("s=urn:t:s3"));
	}

	// ------------------------------------------------------------------ definite comparisons

	@Test
	void constantValueEqualToNoStoredTermProvesEmptyOnlyWhenEveryComparisonIsDefinite() {
		String query = "SELECT ?s WHERE { ?s :v ?o FILTER(?o = 3) }";
		long mask = generatedRuleMask(PackedQueryCodec.encodeForPlanning(parse(query), NON_CANONICAL_NUMERIC_PROVIDER));
		assertTrue((mask & PackedRuleProofs.PREDICATE_RANGE_EMPTY) != 0L,
				"3 is definitely unequal to each of 1, 01, 1.0 and 2, so the filter is a proven contradiction");
		assertPackedPlanPreservesResults(nonCanonicalNumericData(), query, SUBJECT_LOOKUP_COSTS,
				NON_CANONICAL_NUMERIC_PROVIDER, List.of());
	}

	@Test
	void incompatibleStringConstantAgainstNumericDomainProvesEmpty() {
		String query = "SELECT ?s WHERE { ?s :v ?o FILTER(?o = \"1\") }";
		long mask = generatedRuleMask(PackedQueryCodec.encodeForPlanning(parse(query), NON_CANONICAL_NUMERIC_PROVIDER));
		assertTrue((mask & PackedRuleProofs.PREDICATE_RANGE_EMPTY) != 0L,
				"a string never value-equals a numeric literal (type error for every row)");
		assertPackedPlanPreservesResults(nonCanonicalNumericData(), query, SUBJECT_LOOKUP_COSTS,
				NON_CANONICAL_NUMERIC_PROVIDER, List.of());
	}

	// ------------------------------------------------------------------ strict/extended disagreement -> refuse

	@Test
	void durationConstantWhoseEqualityDependsOnComparisonModeIsNeitherAnchoredNorProvedEmpty() {
		String query = "SELECT ?s WHERE { ?s :u ?o FILTER(?o = \"P1Y\"^^xsd:duration) }";
		long mask = generatedRuleMask(PackedQueryCodec.encodeForPlanning(parse(query), FINITE_DURATION_PROVIDER));
		assertEquals(0L, mask & (PackedRuleProofs.PREDICATE_RANGE_ANCHOR | PackedRuleProofs.PREDICATE_RANGE_EMPTY),
				"strict comparison finds P12M unequal to P1Y while extended comparison finds them equal, so the "
						+ "planner (which does not know the strategy's mode) must keep the original filter; mask=0x"
						+ Long.toHexString(mask));
		Model data = model();
		add(data, "s1", "u", VF.createLiteral("P12M", CoreDatatype.XSD.DURATION));
		add(data, "s2", "u", VF.createLiteral("P2Y", CoreDatatype.XSD.DURATION));
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, FINITE_DURATION_PROVIDER, null);
	}

	@Test
	void dateTimeConstantAgainstFiniteDateDomainPreservesResults() {
		// Both comparison modes drop every row here (extended calendar comparison of a date against a dateTime is
		// indeterminate), so a contradiction proof is admissible; the result bag must be preserved either way.
		String query = "SELECT ?s WHERE { ?s :d ?o FILTER(?o = \"2020-01-01T00:00:00\"^^xsd:dateTime) }";
		Model data = model();
		add(data, "s1", "d", VF.createLiteral("2020-01-01", CoreDatatype.XSD.DATE));
		add(data, "s2", "d", VF.createLiteral("2021-06-30", CoreDatatype.XSD.DATE));
		assertPackedPlanPreservesResults(data, query, SUBJECT_LOOKUP_COSTS, FINITE_DATE_PROVIDER, List.of());
	}

	// ------------------------------------------------------------------ nothing else changes

	@Test
	void anchorDoesNotProveSiblingJoinEmpty() {
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(
				parse("SELECT ?s ?t WHERE { { ?s :v ?o FILTER(?o = 1) } ?t :w ?o }"), NON_CANONICAL_NUMERIC_PROVIDER);
		assertFalse(predicateRangeEmptyGroups(packed).contains(packed.relGroup(packed.rootRelId())));
	}

	private static List<Set<Value>> finiteDomains(TupleExpr root, String bindingName) {
		List<Set<Value>> domains = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				if (!node.getBindingNames().contains(bindingName)) {
					return;
				}
				Set<Value> values = new LinkedHashSet<>();
				node.getBindingSets().forEach(bindingSet -> {
					if (bindingSet.hasBinding(bindingName)) {
						values.add(bindingSet.getValue(bindingName));
					}
				});
				domains.add(Set.copyOf(values));
			}
		});
		return domains;
	}
}
